import {filterProtection} from './archive.mjs';
import {protectionMessage} from './messages.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>protectionMessage(k,I18n.language),number=(v,d=3)=>Number.isFinite(v)?new Intl.NumberFormat(I18n.locale,{maximumFractionDigits:d}).format(v):t('notSupplied');
const rowsHTML=rows=>'<dl class="environment-facts">'+rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v??t('notSupplied'))}</dd></div>`).join('')+'</dl>';
export class ProtectionController{
  constructor(container,repository,service,{openPanel=()=>{},isOpen=()=>false,onChange=()=>{}}={}){
    Object.assign(this,{container,repository,service,openPanel,isOpen,onChange,data:null,map:null,group:null,worker:null,busy:false,status:'',selected:null,result:null,page:0,importGeneration:0,queryPoint:{lat:'',lon:''},filters:{search:'',realm:'all',siteType:'all',noTake:'all',show:true}});container.dataset.userContent='';
    container.addEventListener('click',e=>{const action=e.target.closest('[data-protection-action]')?.dataset.protectionAction;if(action==='import')container.querySelector('input[type=file]').click();if(action==='fit')this.fit();if(action==='siteFit')this.fit(this.selected?[this.selected]:[]);if(action==='remove')this.remove();if(action==='next'){this.page++;this.render();}if(action==='previous'&&this.page){this.page--;this.render();}const pick=e.target.closest('[data-protection-id]');if(pick){const f=this.data?.features.find(f=>f.id===pick.dataset.protectionId);if(f)this.select(f,true);}});
    container.addEventListener('change',e=>{if(e.target.type==='file'){if(e.target.files[0])this.importFile(e.target.files[0]);return;}const key=e.target.dataset.protectionFilter;if(key&&key!=='search'){this.filters[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;this.page=0;this.selected=null;this.render();}});
    container.addEventListener('input',e=>{if(e.target.dataset.protectionFilter==='search'){this.filters.search=e.target.value;this.page=0;this.selected=null;const pos=e.target.selectionStart;this.render();const input=container.querySelector('[data-protection-filter=search]');input.focus();input.setSelectionRange(pos,pos);}if(['latitude','longitude'].includes(e.target.name)){this.readPoint();this.result=null;container.querySelector('[data-protection-result]')?.replaceChildren();}});
    container.addEventListener('submit',e=>{e.preventDefault();this.readPoint();this.query(this.queryPoint.lat===''?NaN:Number(this.queryPoint.lat),this.queryPoint.lon===''?NaN:Number(this.queryPoint.lon));});this.render();
  }
  readPoint(){const form=this.container.querySelector('form');if(form)this.queryPoint={lat:form.elements.latitude.value,lon:form.elements.longitude.value};}
  async restore(){const data=await this.repository.load();if(!this.data&&data){this.data=data;this.status=this.repository.persistence==='memory'?'memory':'';this.render();this.onChange();}}
  attachMap(map){if(this.map===map)return;this.map=map;map.createPane('protectedAreasPane').style.zIndex=450;this.renderer=window.L.canvas({pane:'protectedAreasPane',padding:.15});map.on('click',e=>{if(this.isOpen()&&this.data)this.query(e.latlng.lat,e.latlng.lng);});this.draw();}
  async importFile(file){const generation=++this.importGeneration;this.worker?.terminate();this.busy=true;this.status='';this.render();try{
    if(!file.size||file.size>25*1024*1024||!file.name.toLowerCase().endsWith('.zip'))throw Error('invalid_archive_file');const bytes=await file.arrayBuffer();if(generation!==this.importGeneration)return;const worker=new Worker(new URL('./import-worker.mjs',import.meta.url),{type:'module'});this.worker=worker;
    const data=await new Promise((resolve,reject)=>{worker.onmessage=e=>e.data.ok?resolve(e.data.data):reject(Error(e.data.error));worker.onerror=()=>reject(Error('archive_worker_failed'));worker.postMessage({bytes,fileName:file.name},[bytes]);});worker.terminate();if(generation!==this.importGeneration)return;await this.repository.save(data);if(generation!==this.importGeneration)return;this.data=data;this.selected=null;this.result=null;this.page=0;this.status=this.repository.persistence==='memory'?'memory':'';this.onChange();this.fit(data.features);
    }catch(error){if(generation===this.importGeneration){this.status='error';this.errorCode=error.message;}}finally{if(generation===this.importGeneration){this.busy=false;this.render();}}}
  async remove(){++this.importGeneration;this.worker?.terminate();try{await this.repository.remove();this.data=null;this.selected=null;this.result=null;this.status='';this.busy=false;this.render();this.onChange();}catch{this.status='error';this.render();}}
  render(){
    const data=this.data,m=data?.metadata,f=this.filters;this.filtered=data?filterProtection(data,f):[];const count=this.filtered.length;this.page=Math.min(this.page,Math.max(0,Math.ceil(count/8)-1));
    const select=(key,options)=>`<select data-protection-filter="${key}">${options.map(([value,label])=>`<option value="${esc(value)}" ${f[key]===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
    this.container.innerHTML=`<div class="observation-intro"><span class="workbench-tag">${esc(t('research'))}</span><h3>${esc(t('title'))}</h3><p>${esc(t('local'))}</p></div><p class="protection-license">${esc(t('license'))}</p><input type="file" accept=".zip" hidden><button class="btn primary full" data-protection-action="import" ${this.busy?'disabled':''}>${esc(t(this.busy?'importing':'import'))}</button>${this.status?`<p class="environment-query-warning" role="status">${esc(t(this.status))}</p>`:''}${data?`
      <p class="protection-release">${esc(t('release'))} <strong>${esc(m.release)}</strong> · WGS 84</p><p class="small-note">${esc(t('snapshot'))}</p><div class="observation-summary"><div><strong>${number(m.recordCount,0)}</strong><span>${esc(t('records'))} · ${number(m.uniqueSiteCount,0)} ${esc(t('sites'))}</span></div><div><strong>${number(count,0)}</strong><span>${esc(t('matching'))}</span></div></div><label class="environment-checkbox"><input type="checkbox" data-protection-filter="show" ${f.show?'checked':''}><span>${esc(t('show'))}</span></label>
      <label class="protection-search"><span class="sr-only">${esc(t('search'))}</span><input type="search" data-protection-filter="search" value="${esc(f.search)}" placeholder="${esc(t('search'))}"></label><div class="observation-filters"><label>${esc(t('realm'))}${select('realm',[['all',t('all')],['Marine',t('marine')],['Coastal',t('coastal')],['Terrestrial',t('terrestrial')]])}</label><label>${esc(t('kind'))}${select('siteType',[['all',t('all')],['PA',t('pa')],['OECM',t('oecm')]])}</label></div><label>${esc(t('noTake'))}${select('noTake',[['all',t('all')],...Object.keys(m.counts.noTake).map(k=>[k,k])])}</label><button class="btn secondary full" data-protection-action="fit" ${count?'':'disabled'}>${esc(t('fit'))}</button><p class="small-note">${esc(t('subset'))}</p><div class="protection-list">${this.filtered.slice(this.page*8,this.page*8+8).map(item=>`<button class="observation-row" data-protection-id="${esc(item.id)}"><span>${esc(item.properties.NAME_ENG||item.properties.NAME)}<small>${esc(item.properties.ISO3)} · ${esc(item.properties.REALM)} · ${esc(t(item.shape.type==='Polygon'?'polygon':'point'))}</small></span><span>↗</span></button>`).join('')}</div>${!count?`<p>${esc(t('noMatches'))}</p>`:''}${count>8?`<div class="observation-pagination"><button class="text-link" data-protection-action="previous" aria-label="${esc(t('previous'))}" ${this.page?'':'disabled'}>←</button><span>${this.page*8+1}–${Math.min(count,this.page*8+8)} / ${count}</span><button class="text-link" data-protection-action="next" aria-label="${esc(t('next'))}" ${count>(this.page+1)*8?'':'disabled'}>→</button></div>`:''}
      ${this.selected?this.selectionHTML(this.selected):''}<form class="environment-query protection-query"><h3>${esc(t('check'))}</h3><p>${esc(t('mapHint'))}</p><div class="environment-coordinate-fields"><label>${esc(t('latitude'))}<input type="number" name="latitude" min="-90" max="90" step="any" required value="${esc(this.queryPoint.lat)}"></label><label>${esc(t('longitude'))}<input type="number" name="longitude" min="-180" max="180" step="any" required value="${esc(this.queryPoint.lon)}"></label></div><button type="submit" class="btn secondary full">${esc(t('check'))}</button></form><div data-protection-result role="status">${this.resultHTML()}</div>
      `:`<p>${esc(t('empty'))}</p>`}<details class="environment-notes"><summary>${esc(t('source'))}</summary><p>${esc(t('noTakeNote'))}</p><p>${esc(t('pointNote'))}</p><p>${esc(t('uncertainty'))}</p><p>${esc(t('schema'))}</p>${data?rowsHTML([['SHA-256',m.archiveSha256],[t('records'),`${m.polygonCount} polygon · ${m.pointRecordCount} point`],['SITE_TYPE',Object.entries(m.counts.siteType).map(([k,n])=>k+': '+n).join(' · ')],['ISO3',Object.entries(m.counts.iso3).map(([k,n])=>k+': '+n).join(' · ')]]):''}${data?`<p class="protection-citation">${esc(m.citation)}</p>`:''}<div class="protection-source-links"><a href="https://www.protectedplanet.net/" target="_blank" rel="noopener">Protected Planet ↗</a><a href="https://www.protectedplanet.net/en/legal" target="_blank" rel="noopener">${esc(t('terms'))} ↗</a><a href="https://www.ibat-alliance.org/" target="_blank" rel="noopener">${esc(t('commercial'))} ↗</a></div></details>${data?`<button class="text-link observation-remove" data-protection-action="remove">${esc(t('remove'))}</button>`:''}`;
    const badge=document.getElementById('protectionOverlayBadge');if(badge){badge.hidden=!data||!f.show;badge.textContent=t('protection')+' · '+(m?.release||'')+' · '+t('research');}this.draw();
  }
  selectionHTML(item){const p=item.properties,source=this.data.metadata.usedSources.find(s=>String(s.METADATAID)===String(p.METADATAID));return `<div class="observation-selection protection-selection"><h3>${esc(p.NAME_ENG||p.NAME)}</h3><span class="workbench-tag">${esc(t(item.shape.type==='Polygon'?'polygon':'point'))}</span>${rowsHTML([['SITE_ID / SITE_PID',item.siteId+' / '+item.id],[t('kind'),p.SITE_TYPE],[t('realm'),p.REALM],[t('status'),p.STATUS],[t('year'),p.STATUS_YR],[t('noTake'),p.NO_TAKE],[t('reportedArea'),number(p.REP_AREA)],[t('gisArea'),number(p.GIS_AREA)],[t('marineArea'),number(p.REP_M_AREA)],[t('verification'),p.VERIF]])}<button class="btn secondary full" data-protection-action="siteFit">${esc(t('fit'))}</button><p>${esc(t('yearNote'))}</p><p>${esc(t('noTakeNote'))}</p><p>${esc(t('areaNote'))}</p><details class="environment-notes"><summary>${esc(t('source'))}</summary>${rowsHTML([[t('authority'),p.MANG_AUTH],['METADATAID',p.METADATAID],[t('source'),source?.DATA_TITLE],[t('sourceScale'),source?.SCALE],['Part',item.sourcePart],['DBF row',item.sourceRow]])}</details></div>`;}
  resultHTML(){const r=this.result;if(!r)return '';return `<div class="protection-query-result"><p class="environment-query-warning">${esc(t(r.status))}</p>${r.source?`<small>${esc(t('release'))} · ${esc(r.source.release)}</small>`:''}${r.matches.map(m=>`<button class="observation-row" data-protection-id="${esc(m.id)}"><span>${esc(m.name)}<small>${esc(t(m.relation))} · ${esc(m.id)}</small></span><span>↗</span></button>`).join('')}<p class="small-note">${esc(t('subset'))}</p></div>`;}
  query(lat,lon){this.queryPoint={lat:String(lat),lon:String(lon)};this.result=this.service.getProtectionAt(lat,lon);this.render();this.container.querySelector('[data-protection-result]')?.scrollIntoView({block:'nearest',behavior:'instant'});}
  select(item,fit=false){this.selected=item;this.openPanel('protection');this.render();if(fit)this.fit([item]);this.container.querySelector('.protection-selection')?.scrollIntoView({block:'nearest',behavior:'instant'});}
  draw(){if(!this.map)return;const L=window.L;if(this.group)this.map.removeLayer(this.group);this.group=null;const credit='Protected Planet · UNEP-WCMC / IUCN';if(this.creditShown){this.map.attributionControl.removeAttribution(this.credit);this.creditShown=false;}if(!this.data||!this.filters.show)return;this.group=L.layerGroup().addTo(this.map);this.credit=`<a href="https://www.protectedplanet.net/" target="_blank" rel="noopener">${credit}</a> · ${esc(this.data.metadata.release)}`;this.map.attributionControl.addAttribution(this.credit);this.creditShown=true;
    for(const item of this.filtered){const selected=this.selected?.id===item.id,options={renderer:this.renderer,pane:'protectedAreasPane',color:selected?'#225b49':'#3c8067',weight:selected?2.5:1.5,opacity:.95,fillColor:'#6ba58b',fillOpacity:selected ? .22 : .1,fillRule:'evenodd',smoothFactor:.6,bubblingMouseEvents:false};const layers=item.shape.type==='Polygon'?[L.polygon(item.shape.coordinates.map(r=>r.map(([x,y])=>[y,x])),options)]:item.shape.coordinates.map(([x,y])=>L.circleMarker([y,x],{...options,radius:6,fillOpacity:.85}));for(const layer of layers){const label=document.createElement('span');label.textContent=(item.properties.NAME_ENG||item.properties.NAME)+' · '+t(item.shape.type==='Polygon'?'polygon':'point');layer.bindTooltip(label);layer.on('click',()=>this.select(item));layer.addTo(this.group);}}
  }
  fit(items=this.filtered){if(!this.map||!items?.length)return;this.filters.show=true;const b=items.reduce((b,f)=>[Math.min(b[0],f.shape.bbox[0]),Math.min(b[1],f.shape.bbox[1]),Math.max(b[2],f.shape.bbox[2]),Math.max(b[3],f.shape.bbox[3])],[Infinity,Infinity,-Infinity,-Infinity]);this.map.fitBounds([[b[1],b[0]],[b[3],b[2]]],{padding:[40,40],maxZoom:9});this.draw();}
}
